from pathlib import Path
import re


def read(path): return Path(path).read_text()
def write(path,text): Path(path).write_text(text)
def must_replace(text, old, new, label, count=1):
    if old not in text: raise SystemExit(f'missing replacement: {label}')
    return text.replace(old,new,count)

def must_regex(text, pattern, repl, label, count=1):
    out,n=re.subn(pattern,repl,text,count=count,flags=re.S)
    if n!=count: raise SystemExit(f'regex {label}: expected {count}, got {n}')
    return out

