assistant_code=r'''async function uploadProof(file){if(!(file instanceof File)||!file.size)return'';const form=new FormData();form.append('file',file,file.name);const result=await api('/api/files?purpose=payment-proof',{method:'POST',body:form,timeout:45000,persist:true});return result.file?.id||''}
function paymentAiSummary(analysis){const parts=[];if(analysis.reference)parts.push(`Operación ${analysis.reference}`);if(Number(analysis.amount||0)>0)parts.push(money(analysis.amount));if(analysis.paymentDate)parts.push(date(analysis.paymentDate));if(analysis.bank||analysis.cheque?.bank)parts.push(analysis.bank||analysis.cheque.bank);if(analysis.recipient||analysis.cheque?.payee)parts.push(`A ${analysis.recipient||analysis.cheque.payee}`);return parts.join(' · ')||'Gemini detectó el medio de pago; revisa los campos antes de confirmar.'}
function setPaymentField(root,name,value){if(value===undefined||value===null||value==='')return;const field=root.querySelector(`[name="${name}"]`);if(field)field.value=String(value)}
function applyPaymentProofAnalysis(root,analysis,methodList){if(!analysis?.detected)throw new Error('Gemini no encontró verificadores de pago legibles en este documento');const method=methodList.find(item=>String(item.kind||'')===String(analysis.methodKind||''));const methodSelect=root.querySelector('#paymentMethod');if(method&&methodSelect){methodSelect.value=method.id;methodSelect.dispatchEvent(new Event('change',{bubbles:true}))}setPaymentField(root,'reference',analysis.reference);setPaymentField(root,'paymentDate',analysis.paymentDate);if(Number(analysis.amount||0)>0){setPaymentField(root,'totalAmount',Math.round(Number(analysis.amount)));const selected=allocationState(root).filter(item=>item.check.checked);if(selected.length===1){selected[0].amount.value=String(Math.min(selected[0].available,Math.round(Number(analysis.amount))));selected[0].amount.disabled=false}}if(analysis.methodKind==='cheque'){setPaymentField(root,'chequeNumber',analysis.cheque?.serialNumber);setPaymentField(root,'chequeCollectionDate',analysis.cheque?.collectionDate);setPaymentField(root,'chequePayee',analysis.cheque?.payee);setPaymentField(root,'chequeAmount',Math.round(Number(analysis.cheque?.amount||analysis.amount||0)));setPaymentField(root,'chequeBank',analysis.cheque?.bank);const status=root.querySelector('[name=status]');if(status)status.value='scheduled'}else if(analysis.paymentDate){const status=root.querySelector('[name=status]');if(status&&status.value!=='disputed')status.value='paid'}const evidence={source:analysis.source||'gemini-payment-proof-v1',methodKind:analysis.methodKind,confidence:Number(analysis.confidence||0),reference:analysis.reference||'',paymentDate:analysis.paymentDate||'',amount:Number(analysis.amount||0),bank:analysis.bank||'',sender:analysis.sender||'',recipient:analysis.recipient||'',accountReference:analysis.accountReference||'',cheque:analysis.cheque||{},warnings:analysis.warnings||[]};root.dataset.paymentProofAnalysis=JSON.stringify(evidence);syncAllocationSummary(root,{forceTotal:false});const statusNode=root.querySelector('[data-payment-ai-status]'),confidence=Math.round(Number(analysis.confidence||0)*100);if(statusNode){statusNode.className='payment-ai-status ok';statusNode.innerHTML=`<strong>Gemini extrajo los verificadores · ${confidence}%</strong><span>${esc(paymentAiSummary(analysis))}</span>${(analysis.warnings||[]).length?`<span>${esc((analysis.warnings||[]).join(' · '))}</span>`:''}`}}
async function analyzePaymentProofFile(file,root,methodList){const status=root.querySelector('[data-payment-ai-status]');if(status){status.className='payment-ai-status';status.innerHTML='<strong>Leyendo comprobante con Gemini…</strong><span>No necesitas copiar manualmente el número de operación, fecha, monto o serie del cheque.</span>'}try{const fileId=await uploadProof(file);if(!fileId)throw new Error('No se pudo guardar el comprobante');root.dataset.paymentProofFileId=fileId;const payload=await api('/api/finance/payment-proof-analysis',{method:'POST',json:{fileId},timeout:75000});applyPaymentProofAnalysis(root,payload.analysis||{},methodList);return payload.analysis}catch(error){if(status){status.className='payment-ai-status warn';status.innerHTML=`<strong>No se pudo completar la lectura automática</strong><span>${esc(error.message)}. Puedes confirmar los datos manualmente y guardar el mismo comprobante.</span>`}return null}}
function bindPaymentProofAssistant(root,methodList){const input=root.querySelector('#paymentProofFile');if(!input)return;input.addEventListener('change',()=>{const file=input.files?.[0];root.dataset.paymentProofFileId='';root.dataset.paymentProofAnalysis='';if(!file)return;root._paymentProofPromise=analyzePaymentProofFile(file,root,methodList).finally(()=>{root._paymentProofPromise=null})})}'''
